var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();var terrain=Terrain.activeTerrain;var td=terrain.terrainData;float Y(float x,float z){return terrain.SampleHeight(new Vector3(x,0,z))+terrain.transform.position.y;}float Creek(float x){return -68+6*Mathf.Sin(x/26)+.025f*x;}float S(float a,float b,float v){return Mathf.SmoothStep(0,1,Mathf.InverseLerp(a,b,v));}float Slope(Vector2 p){return td.GetSteepness((p.x-terrain.transform.position.x)/320,(p.y-terrain.transform.position.z)/320);}bool OldGrove(Vector2 p){return p.x> -63&&p.x<8&&p.y>43&&p.y<142;}
var layout=Newtonsoft.Json.Linq.JObject.Parse(System.IO.File.ReadAllText("ArtSource/Pipeline/Review/BriarwickHamletDev01/Layout.json"));var road=new System.Collections.Generic.List<Vector3>();foreach(var r in layout["routes"]){float half=(float)r["widthMetres"]*.5f;foreach(var q in r["points"])road.Add(new Vector3((float)q[0],(float)q[2],half));}float Road(Vector2 p){float best=999;foreach(var q in road){float dx=q.x-p.x,dz=q.y-p.y;float d=Mathf.Sqrt(dx*dx+dz*dz)-q.z;if(d<best)best=d;}return best;}
Bounds BoundsOf(GameObject go){var rr=go.GetComponentsInChildren<Renderer>().Where(r=>r.enabled&&r.gameObject.activeInHierarchy&&r.gameObject.layer!=2).ToArray();if(rr.Length==0)return new Bounds(Vector3.zero,Vector3.zero);var b=rr[0].bounds;foreach(var r in rr.Skip(1))b.Encapsulate(r.bounds);return b;}
var structures=new System.Collections.Generic.List<Bounds>();foreach(var g in scene.GetRootGameObjects().Where(g=>g.activeInHierarchy&&(g.name.Contains("architectural review")||g.name=="Stable A - rural thatch review03"))){var b=BoundsOf(g);if(b.size.sqrMagnitude>0)structures.Add(b);}foreach(Transform t in GameObject.Find("03 Eleven primary building locations").transform){var b=BoundsOf(t.gameObject);if(b.size.sqrMagnitude>0)structures.Add(b);}var plots=GameObject.Find("04 Common gardens farming and graveyard").GetComponentsInChildren<MeshRenderer>().Select(r=>r.bounds).ToArray();bool InBounds(Vector2 p,Bounds b,float extra){return p.x>=b.min.x-extra&&p.x<=b.max.x+extra&&p.y>=b.min.z-extra&&p.y<=b.max.z+extra;}bool Reserved(Vector2 p,float extra){return structures.Any(b=>InBounds(p,b,extra))||plots.Any(b=>InBounds(p,b,extra));}
bool Safe(Vector2 p,float radius){return p.x> -153&&p.x<153&&p.y> -163&&p.y<143&&!OldGrove(p)&&!Reserved(p,radius+1)&&Road(p)>radius+1.15f&&Mathf.Abs(p.y-Creek(p.x))>3.5f+radius&&Y(p.x,p.y)>4.15f&&Slope(p)<30;}
string Region(Vector2 p){if(Mathf.Abs(p.y-Creek(p.x))<13)return "CreekBanks";if(Mathf.Abs(p.x)<80&&p.y> -55&&p.y<48)return "VillageMargins";if(p.x> -82&&p.x<27&&p.y>35)return "WoodlandSkirts";if(Mathf.Abs(p.x)>126||p.y< -135||p.y>126)return "DistantCountryside";if(Mathf.Abs(p.x)>87||Slope(p)>8||p.y>100)return "Hillsides";return "Meadows";}
var data=Newtonsoft.Json.Linq.JObject.Parse(System.IO.File.ReadAllText("ArtSource/Pipeline/Review/BriarwickEnvironment05/Integration.json"));var defects=new System.Collections.Generic.List<string>();float closestWater=999,closestRoad=999;foreach(var v in data["placements"]){var p=new Vector2((float)v["x"],(float)v["z"]);string type=(string)v["type"];var go=AssetDatabase.LoadAssetAtPath<GameObject>(type=="Heather_A"?"Assets/TerrainSampleAssets/Prefabs/Heather_A.prefab":"Assets/BlightBloom/Art/Environment/Briarwick/Environment02/Prefabs/BW_Environment02_"+type+".prefab");var mesh=go.GetComponent<MeshFilter>().sharedMesh;float reach=Mathf.Max(mesh.bounds.size.x,mesh.bounds.size.z)*(float)v["scale"]*.5f;if(!Safe(p,reach))defects.Add(type+" "+p);closestWater=Mathf.Min(closestWater,Mathf.Abs(p.y-Creek(p.x))-reach-2.1f);closestRoad=Mathf.Min(closestRoad,Road(p)-reach);}var group=GameObject.Find("Environment05 - countryside coverage");var mats=group.GetComponentsInChildren<Renderer>().SelectMany(r=>r.sharedMaterials).Distinct().ToArray();var textures=mats.SelectMany(m=>new[]{m.GetTexture("_BaseMap"),m.GetTexture("_BumpMap")}).Where(t=>t!=null).Distinct().ToArray();var newTextures=textures.Where(t=>AssetDatabase.GetAssetPath(t).Contains("Heather_A")).Select(t=>new{path=AssetDatabase.GetAssetPath(t),t.width,t.height,format=((Texture2D)t).format.ToString(),runtimeBytes=UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(t)}).ToArray();var result=new{placementCount=((Newtonsoft.Json.Linq.JArray)data["placements"]).Count,exclusionDefects=defects,minimumPlantBoundsToWaterEdge=closestWater,minimumPlantBoundsToRoadEdge=closestRoad,newTextures,newTextureRuntimeBytes=newTextures.Sum(t=>t.runtimeBytes),meshAssetRuntimeBytes=group.GetComponentsInChildren<MeshFilter>().Select(f=>f.sharedMesh).Distinct().Sum(m=>UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(m)),newMaterialCount=1};System.IO.File.WriteAllText("ArtSource/Pipeline/Review/BriarwickEnvironment05/PlacementPerformance.json",Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));return result;